<?php
require_once __DIR__ . '/../config/database.php';
requireAdmin();
$requestedMonth=(string)($_GET['month'] ?? date('Y-m'));
$monthDate=DateTimeImmutable::createFromFormat('!Y-m-d',$requestedMonth.'-01');
if (!$monthDate || $monthDate->format('Y-m') !== $requestedMonth) { $monthDate=new DateTimeImmutable('first day of this month'); }
$month=$monthDate->format('Y-m'); $start=$monthDate->format('Y-m-d'); $end=$monthDate->modify('+1 month')->format('Y-m-d');
$summary=['reservation_collected'=>0.0,'bill_collected'=>0.0,'bills_due'=>0,'bills_due_amount'=>0.0,'unpaid_units'=>0,'unpaid_rent_amount'=>0.0,'unverified_count'=>0,'overdue_count'=>0,'overdue_amount'=>0.0,'overdue_units'=>0];
$dueBills=[]; $overdueBills=[]; $billChart=['reservations'=>0.0,'rent'=>0.0]; $dbError=null;
try {
 $pdo=db();
 $q=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM payments WHERE status='paid' AND paid_at >= :start AND paid_at < :end");$q->execute(['start'=>$start,'end'=>$end]);$summary['reservation_collected']=(float)$q->fetchColumn();
 $q=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM tenant_bills WHERE status='paid' AND paid_at >= :start AND paid_at < :end");$q->execute(['start'=>$start,'end'=>$end]);$summary['bill_collected']=(float)$q->fetchColumn();
 $q=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN bill_type='rent' THEN amount ELSE 0 END),0) AS rent_total,COALESCE(SUM(CASE WHEN bill_type IN ('water','electricity','other') THEN amount ELSE 0 END),0) AS utility_total FROM tenant_bills WHERE status='paid' AND paid_at >= :start AND paid_at < :end");$q->execute(['start'=>$start,'end'=>$end]);$revenueRow=$q->fetch();$billChart=['reservations'=>$summary['reservation_collected'],'rent'=>(float)$revenueRow['rent_total']];
 $q=$pdo->prepare("SELECT COUNT(*),COALESCE(SUM(amount),0) FROM tenant_bills WHERE due_date >= :start AND due_date < :end");$q->execute(['start'=>$start,'end'=>$end]);$row=$q->fetch(PDO::FETCH_NUM);$summary['bills_due']=(int)$row[0];$summary['bills_due_amount']=(float)$row[1];
 $q=$pdo->prepare("SELECT COUNT(DISTINCT unit_id),COALESCE(SUM(amount),0) FROM tenant_bills WHERE bill_type='rent' AND due_date >= :start AND due_date < :end AND status IN ('unpaid','overdue','submitted')");$q->execute(['start'=>$start,'end'=>$end]);$row=$q->fetch(PDO::FETCH_NUM);$summary['unpaid_units']=(int)$row[0];$summary['unpaid_rent_amount']=(float)$row[1];
 $q=$pdo->prepare("SELECT COUNT(*) FROM tenant_bills WHERE bill_type='rent' AND due_date >= :start AND due_date < :end AND status='submitted'");$q->execute(['start'=>$start,'end'=>$end]);$summary['unverified_count']=(int)$q->fetchColumn();
 $q=$pdo->query("SELECT COUNT(*),COALESCE(SUM(amount),0),COUNT(DISTINCT unit_id) FROM tenant_bills WHERE due_date < CURDATE() AND status IN ('unpaid','overdue','submitted')");$row=$q->fetch(PDO::FETCH_NUM);$summary['overdue_count']=(int)$row[0];$summary['overdue_amount']=(float)$row[1];$summary['overdue_units']=(int)$row[2];
 $q=$pdo->prepare("SELECT b.id,b.bill_type,b.description,b.amount,b.due_date,b.status,t.full_name,t.email,u.unit_number,a.name AS apartment_name FROM tenant_bills b JOIN tenants t ON t.id=b.tenant_id JOIN units u ON u.id=b.unit_id JOIN apartments a ON a.id=u.apartment_id WHERE b.due_date >= :start AND b.due_date < :end ORDER BY FIELD(b.status,'overdue','unpaid','submitted','paid'),b.due_date ASC,b.id DESC");$q->execute(['start'=>$start,'end'=>$end]);$dueBills=$q->fetchAll();
 $overdueBills=$pdo->query("SELECT b.id,b.bill_type,b.description,b.amount,b.due_date,b.status,t.full_name,t.email,u.unit_number,a.name AS apartment_name FROM tenant_bills b JOIN tenants t ON t.id=b.tenant_id JOIN units u ON u.id=b.unit_id JOIN apartments a ON a.id=u.apartment_id WHERE b.due_date < CURDATE() AND b.status IN ('unpaid','overdue','submitted') ORDER BY b.due_date ASC,b.id DESC LIMIT 100")->fetchAll();
} catch(Throwable $exception) { $dbError='Monthly results need the tenant-billing migration and current MySQL connection.'; }
$totalCollected=$summary['reservation_collected']+$summary['bill_collected'];
$pageTitle='Monthly results';$currentAdminPage='reports';require __DIR__.'/partials/header.php';
?>
<section class="report-heading"><div><p class="admin-kicker">PROPERTY DESK / REPORTING</p><h2><?= e($monthDate->format('F Y')) ?> results</h2><p>Collections recorded and tenant balances due for the selected month.</p></div><form method="get" class="report-month-picker"><label for="report-month">Reporting month</label><div><input id="report-month" type="month" name="month" value="<?= e($month) ?>" required><button class="button button-dark" type="submit">View month</button></div></form></section>
<?php if($dbError): ?><div class="database-notice" role="status"><strong>Report unavailable.</strong><span><?= e($dbError) ?></span></div><?php endif; ?>
<section class="report-stat-grid" aria-label="Monthly financial results">
 <article class="report-stat report-stat-primary"><span>Payments collected</span><strong><?= pesos($totalCollected) ?></strong><small>Reservation records + verified tenant bills</small></article>
 <article class="report-stat report-stat-alert"><span>Rent units not verified paid</span><strong><?= $summary['unpaid_units'] ?></strong><small><?= pesos($summary['unpaid_rent_amount']) ?> unverified rent charges due this month (submitted references are not yet verified)</small></article>
 <article class="report-stat"><span>Bills due this month</span><strong><?= $summary['bills_due'] ?></strong><small><?= pesos($summary['bills_due_amount']) ?> total billed</small></article>
 <article class="report-stat report-stat-alert"><span>Overdue now</span><strong><?= $summary['overdue_count'] ?></strong><small><?= pesos($summary['overdue_amount']) ?> across <?= $summary['overdue_units'] ?> units</small></article>
</section>
<?php $pieTotal=array_sum($billChart);$reservationEnd=$pieTotal>0?$billChart['reservations']/$pieTotal*100:0;$rentEnd=$reservationEnd+($pieTotal>0?$billChart['rent']/$pieTotal*100:0); ?>
<section class="report-chart-panel"><div class="report-chart-copy"><p class="eyebrow">MONEY COLLECTED</p><h2><?= e($monthDate->format('F Y')) ?> revenue</h2><p>Verified reservation and rent receipts recorded during the selected month. Utilities and other charges are excluded from this chart.</p><ul class="report-chart-legend"><li><span class="chart-swatch chart-paid"></span><span>Reservation payments</span><strong><?= pesos($billChart['reservations']) ?></strong></li><li><span class="chart-swatch chart-pending"></span><span>Rent collected</span><strong><?= pesos($billChart['rent']) ?></strong></li></ul><p class="report-chart-total">Total money collected: <strong><?= pesos($pieTotal) ?></strong></p></div><div class="report-pie-wrap"><div class="report-pie <?= $pieTotal<=0 ? 'report-pie-empty' : '' ?>" style="--reservation-end:<?= number_format($reservationEnd,2,'.','') ?>%;--rent-end:<?= number_format($rentEnd,2,'.','') ?>%" role="img" aria-label="Monthly reservation and rent collected"><span><?= $pieTotal>0 ? pesos($pieTotal) : 'No receipts' ?><small><?= $pieTotal>0 ? 'collected' : 'this month' ?></small></span></div></div></section>
<section class="report-collection-strip"><div><span>Reservation payments</span><strong><?= pesos($summary['reservation_collected']) ?></strong></div><div><span>Verified bills</span><strong><?= pesos($summary['bill_collected']) ?></strong></div><div><span>Rent references awaiting verification</span><strong><?= (int)$summary['unverified_count'] ?></strong></div></section>
<section class="admin-panel report-panel"><div class="panel-heading"><div><p class="eyebrow">SELECTED MONTH</p><h2>Bills due in <?= e($monthDate->format('F')) ?></h2></div><a class="text-link" href="billing.php">Manage billing →</a></div><?php if(!$dueBills): ?><div class="admin-empty">No bills are due in this month.</div><?php else: ?><div class="admin-table-wrap"><table class="admin-table admin-table-wide"><thead><tr><th>Tenant / unit</th><th>Bill</th><th>Due date</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($dueBills as $b): ?><tr class="<?= in_array($b['status'],['unpaid','overdue'],true)?'report-row-unpaid':'' ?>"><td><strong><?= e($b['full_name']) ?></strong><small><?= e($b['apartment_name']) ?> · Unit <?= e($b['unit_number']) ?></small></td><td><?= e(ucfirst($b['bill_type'])) ?><small><?= e($b['description']) ?></small></td><td><?= e(date('M j, Y',strtotime($b['due_date']))) ?></td><td><strong><?= pesos((float)$b['amount']) ?></strong></td><td><span class="status-pill status-<?= e($b['status']) ?>"><?= e(str_replace('_',' ',$b['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="admin-panel report-panel"><div class="panel-heading"><div><p class="eyebrow">ACTION REQUIRED</p><h2>Overdue payments</h2></div><span class="report-alert-count"><?= count($overdueBills) ?> open<?= count($overdueBills)===100?' +':'' ?></span></div><?php if(!$overdueBills): ?><div class="admin-empty">No overdue bills are currently outstanding.</div><?php else: ?><div class="admin-table-wrap"><table class="admin-table admin-table-wide"><thead><tr><th>Tenant / unit</th><th>Bill</th><th>Due</th><th>Days late</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($overdueBills as $b): $daysLate=max(0,(int)(new DateTimeImmutable($b['due_date']))->diff(new DateTimeImmutable('today'))->format('%r%a')); ?><tr class="report-row-unpaid"><td><strong><?= e($b['full_name']) ?></strong><small><?= e($b['apartment_name']) ?> · Unit <?= e($b['unit_number']) ?></small></td><td><?= e(ucfirst($b['bill_type'])) ?><small><?= e($b['description']) ?></small></td><td><?= e(date('M j, Y',strtotime($b['due_date']))) ?></td><td><strong><?= $daysLate ?></strong></td><td><strong><?= pesos((float)$b['amount']) ?></strong></td><td><span class="status-pill status-<?= e($b['status']) ?>"><?= e($b['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php require __DIR__.'/partials/footer.php'; ?>
